        if chosen_channel is None and _is_channel_valid(channel_res):
            chosen_channel = channel_res
        is_fallback = chosen_channel is None
        if is_fallback:
            win = min(n, max(15, min(30, int(n * 0.5))))
            r_slice = close[-win:]
